func (q *Queries) SampleUnverifiedGrants(ctx context.Context, arg SampleUnverifiedGrantsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, sampleUnverifiedGrants, arg.AuthorityID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setAuthorityKeyState = `-- name: SetAuthorityKeyState :one
UPDATE consent_authority_keys SET state = $1::text, changed_at = now()
WHERE authority_id = $2::uuid AND key_id = $3::text
  AND (state = 'active' OR state = 'retired' AND $1::text = 'compromised')
RETURNING id, authority_id, key_id, public_key, state, added_by, added_at, changed_at
`

type SetAuthorityKeyStateParams struct {
	State       string
	AuthorityID string
	KeyID       string
}

// Retires an active key, or marks an active or retired key compromised; compromise is final.
func (q *Queries) SetAuthorityKeyState(ctx context.Context, arg SetAuthorityKeyStateParams) (ConsentAuthorityKey, error) {
	row := q.db.QueryRow(ctx, setAuthorityKeyState, arg.State, arg.AuthorityID, arg.KeyID)
	var i ConsentAuthorityKey
	err := row.Scan(
		&i.ID,
		&i.AuthorityID,
		&i.KeyID,
		&i.PublicKey,
		&i.State,
		&i.AddedBy,
		&i.AddedAt,
		&i.ChangedAt,
	)
	return i, err
}

const suspendAuthorityAutomatically = `-- name: SuspendAuthorityAutomatically :execrows
UPDATE consent_authorities SET state = 'suspended' WHERE id = $1 AND state = 'active'
`

func (q *Queries) SuspendAuthorityAutomatically(ctx context.Context, id string) (int64, error) {
	result, err := q.db.Exec(ctx, suspendAuthorityAutomatically, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

